"""연령 확인 (만 14세 미만 차단)."""
from datetime import date, datetime

MIN_AGE = 14

def validate_age(birth_date_str: str) -> None:
    """
    생년월일을 받아 만 14세 미만이면 ValueError를 발생시킵니다.
    """
    try:
        b_date = datetime.strptime(birth_date_str, "%Y-%m-%d").date()
    except ValueError:
        raise ValueError("birth_date must be in YYYY-MM-DD format")

    today = date.today()
    age = today.year - b_date.year - ((today.month, today.day) < (b_date.month, b_date.day))

    if age < MIN_AGE:
        raise ValueError(
            f"Users must be at least {MIN_AGE} years old to use this service."
        )
